def contar_ocurrencias():
    entrada = input()  # Complejidad: n (donde n es el número de caracteres en la entrada)
    numeros = list(map(int, entrada.split()))  # Complejidad: n (dividir y convertir a enteros)
    orden = []  # Complejidad: 1
    contador = {}  # Complejidad: 1
    for numero in numeros:  # Complejidad del bucle: m (donde m es el número de números enteros)
        if numero in contador:  # Complejidad: 1 (promedio)
            contador[numero] += 1  # Complejidad: 1
        else:
            contador[numero] = 1  # Complejidad: 1
            orden.append(numero)  # Complejidad: 1 (amortizada)
    for numero in orden:  # Complejidad del bucle: k (donde k es el número de números únicos)
        print(f"{numero} {contador[numero]}")  # Complejidad: 1
