def determinar_estructura(operaciones):
    from collections import deque
    import heapq

    pila = []
    cola = deque()
    cola_prioridad = []
    es_cola = True

    es_pila = True
    es_cola_prioridad = True

    for operacion in operaciones:
        tipo, x = operacion

        if tipo == 1:
            if es_pila:
                pila.append(x)
            if es_cola:
                cola.append(x)
            if es_cola_prioridad:
                heapq.heappush(cola_prioridad, -x)  
        elif tipo == 2:
            if es_pila:
                if pila and pila[-1] == x:
                    pila.pop()
                else:
