def process_operations(n, operations):
    stack = []
    queue = deque()
    priority_queue = []

    is_stack = True
    is_queue = True
    is_priority_queue = True

    for op in operations:
        cmd, x = op[0], op[1]
        if cmd == 1:
            stack.append(x)
            queue.append(x)
            priority_queue.append(x)
        elif cmd == 2:
            if not stack or not queue or not priority_queue:
                return "impossible"
