def generate_parentheses(n):
    result = []
    stack = []

    def backtrack(left, right):
        if left == 0 and right == 0:
            result.append(''.join(stack))
            return

        if left > 0:
            stack.append('(')
            backtrack(left - 1, right)
            stack.pop()

        if right > left:
            stack.append(')')
            backtrack(left, right - 1)
            stack.pop()

    backtrack(n, n)
    return result

