def simulate_ball_drop(depth, ball_number):
    tree_size = 2**depth - 1

    current_position = 1
    flags = [False] * (tree_size + 1)  # +1 porque los nodos empiezan en 1
    for _ in range(ball_number):
        current_position = 1  # Empezamos desde la raíz para cada bola
        while current_position <= tree_size // 2:  # Mientras no sea una hoja
            if not flags[current_position]:
                flags[current_position] = True
                current_position = current_position * 2  # Ir al hijo izquierdo
            else:
                flags[current_position] = False
                current_position = current_position * 2 + 1  # Ir al hijo derecho

    return current_position

def main():
    num_cases = int(input())
    for _ in range(num_cases):
        depth, ball_number = map(int, input().split())
        result = simulate_ball_drop(depth, ball_number)
        print(result)

