from collections import deque

def es_primo(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def generar_primos():
    primos = []
    for num in range(1000, 10000):
        if es_primo(num):
            primos.append(num)
    return primos

def obtener_vecinos(primo, primos_set):
    vecinos = []
    str_primo = str(primo)
    for i in range(4):
        for d in '0123456789':
            if d != str_primo[i]:
                nuevo_primo = str_primo[:i] + d + str_primo[i+1:]
                if nuevo_primo[0] != '0' and int(nuevo_primo) in primos_set:
                    vecinos.append(int(nuevo_primo))
    return vecinos

def bfs_camino_mas_corto(inicio, fin, primos_set):
    if inicio == fin:
        return 0

    queue = deque([(inicio, 0)])
    visitados = set()
    visitados.add(inicio)

    while queue:
        actual, costo = queue.popleft()

        for vecino in obtener_vecinos(actual, primos_set):
            if vecino not in visitados:
                if vecino == fin:
                    return costo + 1
                visitados.add(vecino)
                queue.append((vecino, costo + 1))

    return "Imposible"

def resolver_casos_de_prueba(casos):
    primos = generar_primos()
    primos_set = set(primos)

    resultados = []
    for inicio, fin in casos:
        resultado = bfs_camino_mas_corto(inicio, fin, primos_set)
        resultados.append(resultado)

    return resultados

