def contar_anagramas(casos):
    resultados = []

    for caso in casos:
        n, palabras = caso
        forma_canonica = {}

        for palabra in palabras:
            canonica = ''.join(sorted(palabra))
            if canonica in forma_canonica:
                forma_canonica[canonica] += 1
            else:
                forma_canonica[canonica] = 1

        resultado_caso = [
            forma_canonica[''.join(sorted(palabra))] - 1 for palabra in palabras
        ]
        resultados.append(resultado_caso)

    return resultados

