def calculate_distance(keyboard, word):
    position = {char: idx for idx, char in enumerate(keyboard)}
    total_distance = 0
    for i in range(1, len(word)):
        curr_char = word[i]
        prev_char = word[i - 1]
        total_distance += abs(position[curr_char] - position[prev_char])
    return total_distance

def main():
    num_cases = int(input().strip())
    for _ in range(num_cases):
        keyboard = input().strip()
        word = input().strip()
        distance = calculate_distance(keyboard, word)
        print(distance)
if __name__ == "__main__":
    main()

def Distancia(k, w):
    p = {char: idx for idx, char in enumerate(k)}
    t = 0
    for i in range(1, len(w)):
        cc = w[i]
        pc = w[i - 1]
        t += abs(p[cc] - p[pc])
    return t

