from collections import Counter
import sys

t = int(sys.stdin.readline())
for _ in range(t):
    S = sys.stdin.readline().strip('\n')
    aux = ''
    NS = ''
    sw = 0

    for s in S:
        if s != ' ':
            aux += s

    C = Counter(aux)
    C = C.most_common(2)
    n = len(C)
    d = ord(C[0][0]) - 69
    if n > 1:
        if C[0][1] != C[1][1]:
            sw = 1
    else:sw = 1

    if d < 0: d = 26 + d

    if sw:
        for s in S:
            c = s
            if c != ' ':
                a = ord(c) - d
                c = chr(91 - (65 - a)) if a < 65 else chr(a)
            NS += c
        sys.stdout.write(str(d) + ' ' + NS + "\n")
    else:
        sys.stdout.write('NOT POSSIBLE\n')

