def ordenarbr(permutaciones,L):
    auxi=0
    contador=0
    for i in range(L-1):
        for j in range(i+1,L):
            if permutaciones[i]>permutaciones[j]:
                auxi=permutaciones[i]
                permutaciones[i]=permutaciones[j]
                permutaciones[j]=auxi
                contador=contador+1
    return contador


