def procesar_texto(entrada):
    buffer = ""
    texto = []
    for linea in entrada:
        linea = linea.strip()
        if linea.endswith('-'):
            buffer += linea[:-1]
        else:
            buffer += linea
            texto.append(buffer)
            buffer = ""
    if buffer:
        texto.append(buffer)
