import re
import sys

def main():
    input = sys.stdin.read
    lines = input().splitlines()
    unique_words = set()
    temp_word = ""

    for line in lines:
        line = line.strip()
        if not line:
            continue

        fragments = re.split(r'(?<!-)\s+', line)
        for idx, fragment in enumerate(fragments):
            if fragment.endswith('-') and idx == len(fragments) - 1:
                temp_word += fragment[:-1]
            else:
                temp_word += fragment
                clean_word = re.sub(r'[^a-zA-Z-]', '', temp_word).lower()
                if clean_word:
                    unique_words.add(clean_word)
                temp_word = ""

    for word in sorted(unique_words):
        print(word)

if __name__ == "__main__":
    main()

import re
import sys

def process_text(lines):
    words_found = set()
    pending_word = ""

    for line in lines:
        if not line.strip():
            continue

        tokens = re.findall(r'[a-zA-Z-]+', line)
        for token in tokens:
            if token.endswith('-') and line.endswith(token):
                pending_word += token[:-1]
            else:
                pending_word += token
                words_found.add(pending_word.lower())
                pending_word = ""

    return sorted(words_found)

def main():
    input = sys.stdin.read
    lines = input().splitlines()
    result = process_text(lines)
    print("\n".join(result))

if __name__ == "__main__":
    main()

