  n = 0
  o = None
  for i, x in enumerate(w):
      if x in ['>', '<', '>=', '<=', '=']:
          o = x
          n = float(w[i + 1])
          break
  t = 0
  a = ''.join(w[:w.index(o)]).split('+')
  for p in a:
      if p in v:
          t += v[p]
  if o == '>':
      return t > n
  if o == '<':
      return t < n
  if o == '>=':
      return t >= n
  if o == '<=':
      return t <= n
  return abs(t - n) < 0.0001

