def evaluar_pronosticos():
    import re

    num_partidos, num_pronosticos = map(int, input().split())
    porcentajes = {
        " ".join(linea[:-1]): float(linea[-1])
        for _ in range(num_partidos)
        for linea in [input().split()]
    }
    pronosticos = [input().strip() for _ in range(num_pronosticos)]

    resultados = []

    operadores = {
        "<": lambda x, y: x < y,
        "<=": lambda x, y: x <= y,
        "=": lambda x, y: x == y,
        ">=": lambda x, y: x >= y,
        ">": lambda x, y: x > y,
    }

    for i, pronostico in enumerate(pronosticos):
        match = re.match(r'(.+?)\s*(<=|<|=|>=|>)\s*(\d+)', pronostico)
        if not match:
            continue

        izquierda, operador, valor_derecha = match.groups()
        valor_derecha = int(valor_derecha)
        partidos = map(str.strip, izquierda.split('+'))

        suma = sum(porcentajes.get(partido, 0.0) for partido in partidos)
        if operadores[operador](round(suma, 1), valor_derecha):
            resultados.append(f"Guess #{i+1} was correct.")
        else:
            resultados.append(f"Guess #{i+1} was incorrect.")

    print("\n".join(resultados))


