    pattern = r'([\w]+|\+|>=|<=|>|<|=|\d+)'
    tokens = re.findall(pattern, guess)
    expected_value = None

    # Variables para el cálculo
    current_sum = 0
    operator = None

    for token in tokens:
        if token in party_percentages:
            current_sum += party_percentages[token]
        elif token == '+':
            continue  # Sumar explícitamente, ya es manejado
        elif token in {'>=', '<=', '=', '>', '<'}:
            operator = token
        elif token.isdigit():
            expected_value = int(token)

    # Evaluar la expresión
    if operator == '>':
        return current_sum > expected_value
    elif operator == '<':
        return current_sum < expected_value
    elif operator == '>=':
        return current_sum >= expected_value
    elif operator == '<=':
        return current_sum <= expected_value
    elif operator == '=':
        return abs(current_sum - expected_value) < 1e-6
    else:
        return False

def main():
    party_percentages, guesses = parse_input()

    results = []
    for i, guess in enumerate(guesses, start=1):
        is_correct = evaluate_guess(party_percentages, guess)
        if is_correct:
            results.append(f"Guess #{i} was correct.")
        else:
            results.append(f"Guess #{i} was incorrect.")

    print("\n".join(results))

