def suma_particiones_iguales(secuencia):
    total = sum(secuencia)
    for suma_particion in range(1, total + 1):
        if total % suma_particion == 0:
            posible = True
            suma_actual = 0
            for num in secuencia:
                suma_actual += num
                if suma_actual > suma_particion:
                    posible = False
                    break
                elif suma_actual == suma_particion:
                    suma_actual = 0
            if posible and suma_actual == 0:
                return suma_particion
    return total

