from collections import Counter
import sys

def process_line(line: str):
    line = line.lower()
    words = line.split()
    all_pairs = []
    for word in words:
        if len(word) >= 2:
            pairs = [word[i:i+2] for i in range(len(word)-1)]
            all_pairs.extend(pairs)
    counter = Counter()
    for pair in all_pairs:
        if pair.isalpha():
            counter[pair] += 1
    filtered = sorted((pair, count) for pair, count in counter.items() if count > 3)
    for pair, count in filtered:
        print(f"{pair} {count}")
    print("----------")

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        process_line(line)

if __name__ == "__main__":
    main()

import sys
from collections import defaultdict

def procesar_linea(linea):
    frecuencia = defaultdict(int)
    palabras = linea.strip().split()

    for palabra in palabras:
        for i in range(len(palabra) - 1):
            par = palabra[i:i+2]
            frecuencia[par] += 1

    resultado = [(par, frecuencia[par]) for par in frecuencia if frecuencia[par] > 3]
    resultado.sort() 

    for par, freq in resultado:
        print(f"{par} {freq}")
    print("----------")

for linea in sys.stdin:
    if linea.strip():
        procesar_linea(linea)

