def crear_matriz_zigzag(filas, columnas):
    matriz = [['.' for _ in range(columnas)] for _ in range(filas)]
    punto_actual = '.'
    i, j = filas - 1, columnas - 1  
    reversa = True

    for _ in range(filas * columnas):
        matriz[i][j] = punto_actual
        punto_actual = 'X' if punto_actual == '.' else '.'

        if reversa:
            j -= 1
            if j < 0:
                i -= 1
                j = 0
                reversa = False
        else:
            j += 1
            if j >= columnas:
                i -= 1
                reversa = True
                j = columnas - 1

    return matriz

