def fac( num ):
    if num == 1:
        return 1

    fact = 1
    for i in range( 2, num +1 ):
        fact *= i

    return fact

def suma( num ):
    num = num[::-1]
    sumando = 0
    size = len( num )

    for i in range( size ):
        sumando += int( num[i] ) * fac( i + 1 )

    return sumando

