    print( suma( num ))

def factorizar(n):
    factor = 2
    factores_primos = []
    while factor * factor <= n:
        while n % factor == 0:
            factores_primos.append(factor)
            n //= factor
        factor += 1
    if n > 1:
        factores_primos.append(n)
    return factores_primos
