    original_n = n
    factores = []
    for primo in primos:
        if primo * primo > n:
            break

        while n % primo == 0:
            factores.append(primo)
            n //= primo
    if n > 1:
        ultimo_primo = primos[-1]
        i = ultimo_primo
        while i * i <= n and n > 1:
            while n % i == 0:
                factores.append(i)
                n //= i
            i += 2

        if n > 1:
            factores.append(n)
    producto = 1
    for f in factores:
        producto *= f
    assert producto == original_n, f"Error: {original_n} != {producto}"

