def generar_criba(n):
    criba = [True] * (n + 1)
    criba[0] = criba[1] = False
    for i in range(2, int(math.isqrt(n)) + 1):
        if criba[i]:
            for j in range(i * i, n + 1, i):
                criba[j] = False
    primos = [i for i, es_primo in enumerate(criba) if es_primo]
    return primos

