from math import isqrt

def criba(n):
    primos = [0, 1] * (n //2)
    primos[:3] = 0, 0, 0
    limite = isqrt(n) + 1
    for p in compress(range(limite), primos):
        primos[p*p : n :p+p] = [0]*len(range(p*p, n , p+p))
    primos[2] = 1
    return [i for i in range(len(primos)) if primos[i]==1]

