import math

def siesprimo(x):
    if x <= 1:
        return False
    limite = math.isqrt(x)
    for i in range(2, limite + 1):
        if x % i == 0:
            return False  # Si es divisible, no es primo
    return True  # Si no encontró divisores, es primo

