def primo(n, primes_set):
    return n in primes_set

def rotate_number(num):
    s = str(num)
    rotations = []
    for i in range(len(s)):
        rotated = int(s[i:] + s[:i])
        rotations.append(rotated)
    return rotations

def is_circular_prime(prime, primes_set):
    rotations = rotate_number(prime)
    return all(primo(rot, primes_set) for rot in rotations)

def sieve_of_eratosthenes(max_num):
    p = 2
    primo = [True] * (max_num + 1)
    while (p * p <= max_num):
        if (primo[p]):
            for i in range(p * p, max_num + 1, p):
                primo[i] = False
        p += 1
    primes = [p for p in range(2, max_num + 1) if primo[p]]
    return primes

def circular(a, b, primes_set):
    count = 0
    for prime in primes_set:
        if prime >= a and prime <= b:
            if is_circular_prime(prime, primes_set):
                count += 1
    return count

def main():
    max_limit = 1000000000
    primes = sieve_of_eratosthenes(1000000)  
    primes_set = set(primes)  
    circular_primes = []
    for prime in primes:
        if is_circular_prime(prime, primes_set):
            circular_primes.append(prime)
    while True:
        line = input().strip()
        if line == "-1":
            break
        a, b = map(int, line.split())
        count = circular(a, b, circular_primes)
        print(count)

