def encontrar_periodo(modulo):
    if modulo <= 0:
        return 0

    a, b = 0, 1
    secuencia = [(0, 1)]

    while True:
        nuevo_b = (a + b) % modulo
        nuevo_a = b % modulo

        if (nuevo_a, nuevo_b) == secuencia[0]:
            return len(secuencia)

        a, b = nuevo_a, nuevo_b
        secuencia.append((a, b))

