def generate_fibonacci(limit):
    fib = [1, 2]
    while fib[-1] <= limit:
        fib.append(fib[-1] + fib[-2])
    return fib[:-1]

def zeckendorf(n):
    if n == 0:
        return []

    fib = generate_fibonacci(n)
    remaining = n
    result = []

    i = len(fib) - 1
    while i >= 0 and remaining > 0:
        if fib[i] <= remaining:
            result.append(fib[i])
            remaining -= fib[i]
            i -= 2
        else:
            i -= 1

    return result

