def sieve_of_eratosthenes(max_num):
    p = 2
    is_prime = [True] * (max_num + 1)
    while (p * p <= max_num):
        if is_prime[p]:
            for i in range(p * p, max_num + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, max_num + 1) if is_prime[p]]

def prime_factors_sum(n, primes):
    factor_sum = 0
    original_n = n
    for prime in primes:
        if prime * prime > n:
            break
        if n % prime == 0:
            factor_sum += prime
            while n % prime == 0:
                n //= prime
    if n > 1:  # If there's a prime factor greater than sqrt(n)
        factor_sum += n
    return factor_sum

def find_ruth_aaron_pairs(a, b, primes):
    pairs = []
    prime_sum_cache = {}

    for n in range(a, b):
        if n not in prime_sum_cache:
            prime_sum_cache[n] = prime_factors_sum(n, primes)
        if (n + 1) not in prime_sum_cache:
            prime_sum_cache[n + 1] = prime_factors_sum(n + 1, primes)

        if prime_sum_cache[n] == prime_sum_cache[n + 1]:
            pairs.append((n, n + 1))

    return pairs

