def criba_eratostenes(n):
    """Genera una lista de números primos hasta n utilizando la criba de Eratóstenes."""
    p = 2
    is_prime = [True] * (n + 1)
    while (p * p <= n):
        if (is_prime[p]):
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, n + 1) if is_prime[p]]

def suma_factores_primos_unicos(num, primos):
    """Devuelve la suma de los factores primos únicos de num."""
    suma = 0
    factores = set()

    # Usa la lista de primos para factorizar el número
    for p in primos:
        if p * p > num:  # Si p^2 es mayor que num, no hay más factores
            break
        while num % p == 0:
            factores.add(p)  # Agregar solo factores únicos
            num //= p
    if num > 1:  # Si num es primo
        factores.add(num)

    return sum(factores)

def encontrar_pares_ruth_aaron(a, b):
    """Encuentra y retorna los pares de Ruth-Aaron en el rango dado [a, b]."""
    primos = criba_eratostenes(b)  # Generar todos los primos hasta b
    suma_factores = [0] * (b + 1)  # Lista para almacenar sumas de factores primos

    for i in range(max(2, a), b + 1):  # Rango desde max(2, a) hasta b
        suma_factores[i] = suma_factores_primos_unicos(i, primos)

    pares = []
    for i in range(max(2, a), b):  # Verificar pares consecutivos
        if suma_factores[i] == suma_factores[i + 1]:
            pares.append((i, i + 1))

    return pares

