from collections import deque

def tiempo_espera(n, m, prioridades):
    # Crear una cola con tuplas (prioridad, índice)
    cola = deque((prioridades[i], i) for i in range(n))
    # Lista para almacenar las prioridades ordenadas
    prioridades_ordenadas = sorted(prioridades, reverse=True)
    idx_prioridad = 0

    tiempo = 0

    while cola:
        actual = cola.popleft()

        # Si la prioridad del primer trabajo es la más alta pendiente de impresión
        if actual[0] == prioridades_ordenadas[idx_prioridad]:
            tiempo += 1
            idx_prioridad += 1
            if actual[1] == m:
                return tiempo
        else:
            cola.append(actual)

    return tiempo

