import sys

class PriorityQueue:
    def __init__(self):
        self.queue = []
        self.numElements = 0

    def isEmpty(self):
        return self.numElements == 0

    def insert(self, data):
        heapq.heappush(self.queue, -data)
        self.numElements += 1

    def get_max(self):
        if not self.isEmpty():
            return -self.queue[0]
        else:
            return None

    def extract_max(self):
        if not self.isEmpty():
            self.numElements -= 1
            return -heapq.heappop(self.queue)
        else:
            return None

    def change_max_priority(self, data):
        if not self.isEmpty():
            heapq.heappop(self.queue)
            heapq.heappush(self.queue, -data)

