    digitos_primos = {2, 3, 5, 7}

    for codigo in codigos:
        digitos = [int(d) for d in codigo]
        digitos_primos_en_codigo = [d for d in digitos if d in digitos_primos]

        if len(digitos_primos_en_codigo) < 3:
            continue

        from itertools import combinations

        encontrado = False
        for combinacion in combinations(digitos_primos_en_codigo, 3):
            if sum(combinacion) % 2 == 0:
                encontrado = True
                break

        if encontrado:
            cantidad_valida += 1

    return cantidad_valida

