import sys
import math
def count_digits_of_factorial(n):
    if n == 0 or n == 1:
        return 1
    log_sum = 0
    for i in range(1, n + 1):
        log_sum += math.log10(i)
    return math.floor(log_sum) + 1
input = sys.stdin.read().strip().split()
for number in input:
    n = int(number)
    print(count_digits_of_factorial(n))

import sys
import math
def factorial(n):
    if n == 0 or n == 1:
        return 1
    lg = 0
    for i in range(1, n + 1):
        lg += math.log10(i)
    return math.floor(lg) + 1
input = sys.stdin.read().strip().split()
for num in input:
    n = int(num)
    print(factorial(n))

