def calculate_wasted_space(containers, packages):
    wasted_space = 0
    container_index = 0
    for package in packages:
        while container_index < len(containers) and containers[container_index] < package:
            wasted_space += containers[container_index]
            container_index += 1
        if container_index < len(containers):
            containers[container_index] -= package
        else:
            break
    while container_index < len(containers):
        wasted_space += containers[container_index]
        container_index += 1

    return wasted_space
