def calcular(c, p):
    w = 0
    ct = 0
    for i in p:
        while ct < len(c) and c[ct] < i:
            w += c[ct]
            ct += 1
        if ct < len(c):
            c[ct] -= i
        else:
            break
    while ct < len(c):
        w += c[ct]
        ct += 1
    return w
