class Nodo:
    item: "Nodo"
    sig: "Nodo"

    def __init__( self, item: str ):
        self.item = item 
        self.sig = None

    def setSig( self, item:"Nodo" ):
        self.sig = item

    def getSig( self )->"Nodo":
        return self.sig

    def getItem( self )->"Nodo":
        return self.item       


class Cola:
    ini: "Nodo"
    fin: "Nodo"

    def __init__( self ):
        self.ini = None
        self.ini = None

    def isVacia( self )->bool:
        return self.ini == None

    def agregar( self, item:str ): 
        newNodo = Nodo( item )

        if self.isVacia():
            self.ini = newNodo
            self.fin = self.ini
        else:
            self.fin.setSig( newNodo )
            self.fin = self.fin.getSig()

    def eliminar( self )->str:
        if self.isVacia():
            return -1
        else:
            devolver = self.ini.getItem()
            self.ini = self.ini.getSig()

        return devolver

    def mostrar( self ):
        devolver = ''
        tmp = self.ini
        while tmp != None:
            devolver += tmp.getItem()
            tmp = tmp.getSig()
        return devolver

#functions
def completarCeros( num:str )->str: 
    num = num[::-1]
    for i in range(8 -len(num) ):
        num += '0'

    return num[::-1]

#main
numAnterior = {}
while True:
    try:
        cola = Cola()
        num, rotar = map( int, input().split() ) 
        rotar = rotar % 8

        if num in numAnterior:
            num = numAnterior[num]
        else:
            numAnterior[num] = completarCeros( bin(num)[2:] )
            num = numAnterior[num]

        for i in num:
            cola.agregar( i )

        for i in range( rotar ):
            cola.agregar( cola.eliminar() )

        print( int(cola.mostrar(),2 ) )

    except EOFError:
        break 
    except Exception as e:
        print( e )
        break

import heapq
import sys

def simular_juegos():
    datos = list(map(int, sys.stdin.read().split()))
    idx = 0

    while idx + 52 <= len(datos):
        J = [-datos[idx + i] for i in range(4)]
        P = [-datos[idx + 4 + i] for i in range(4)]
        v = [-datos[idx + 8 + i] for i in range(44)]
        idx += 52

        heapq.heapify(J)
        heapq.heapify(P)

        i = 0
        while i < 44 and J and P:
            pJ = heapq.heappop(J)
            pP = heapq.heappop(P)

            if pJ > pP:
                heapq.heappush(J, v[i])
            else:
                heapq.heappush(P, v[i])
            i += 1

        if i == 44:
            if len(J) > len(P):
                print("Gana Pedro")
            else:
                print("Gana Juan")
        elif not J:
            print("Gana Juan")
        else:
            print("Gana Pedro")

if __name__ == "__main__":
    simular_juegos()

