def mat_trans(n,matriz):
    trans=[]
    for i in range(n):
        fila=[]
        for j in range(n):
            fila.append(matriz[j][i])
        trans.append(fila)
    return trans

def matriz90(n,matriz):
    matriz=mat_trans(n,matriz)
    m90=[]
    for fila in matriz:
        m90.append(fila[::-1])
    for z in m90:
        print(' '.join(f'{num}' for num in z))


