        m180.append(filainv)
    for z in m180:
        print(' '.join(f'{num}' for num in z))

def matriz270(n,matriz):
    m270=[]
    matriz=mat_trans(n,matriz)
    m270=matriz[::-1]
    for z in m270:
        print(' '.join(f'{num}' for num in z))



