def fibonacci_sequence_up_to(n):
    fib = [1, 2]
    while fib[-1] < n:
        fib.append(fib[-1] + fib[-2])
    if fib[-1] > n:
        fib.pop()
    return fib

def fibonacci_base(n):
    fib = fibonacci_sequence_up_to(n)
    used = False
    result = []
    for f in reversed(fib):
        if n >= f:
            result.append('1')
            n -= f
            used = True
        elif used:
            result.append('0')
    return ''.join(result) if result else '0'

