def sifactors(limit):
    sieve = [[] for _ in range(limit + 1)]
    for i in range(2, limit + 1):
        if not sieve[i]:
            for j in range(i, limit + 1, i):
                sieve[j].append(i)
    return sieve

def numfactors(A, B, sieve):
    result_number = 0
    max_factors = 0
    for num in range(A, B + 1):
        factors = sieve[num]
        if len(factors) > max_factors or (len(factors) == max_factors and num > result_number):
            max_factors = len(factors)
            result_number = num
    return result_number, max_factors

