def criba_factores_primos(limite):
    factores = [0] * (limite + 1)

    # Usamos la criba para marcar los múltiplos de cada primo
    for i in range(2, limite + 1):
        if factores[i] == 0:  # Si es primo
            for j in range(i, limite + 1, i):
                factores[j] += 1  # Contamos el número de factores primos distintos

