    spf = [0] * (max_limit + 1)
    spf[0], spf[1] = 0, 1
    for i in range(2, max_limit + 1):
        if spf[i] == 0:
            spf[i] = i
            for j in range(i * i, max_limit + 1, i):
                if spf[j] == 0:
                    spf[j] = i
    return spf

def count_distinct_prime_factors(spf, max_limit):
    count = [0] * (max_limit + 1)
    for i in range(2, max_limit + 1):
        n = i
        factors = set()
        while n != 1:
            factors.add(spf[n])
            n = n // spf[n]
        count[i] = len(factors)
    return count

