def flip_horizontal(matrix):
    return [row[::-1] for row in matrix]

def flip_vertical(matrix):
    return matrix[::-1]

def matrices_equal(mat1, mat2):
    return all(mat1[i] == mat2[i] for i in range(len(mat1)))

def determine_transformation(N, matrix1, matrix2):
    if matrices_equal(matrix1, matrix2):
        return "sin transformaciones"
    flipped_h = flip_horizontal(matrix1)
    if matrices_equal(flipped_h, matrix2):
        return "flip horizontal"
    flipped_v = flip_vertical(matrix1)
    if matrices_equal(flipped_v, matrix2):
        return "flip vertical"
    flipped_vh = flip_horizontal(flipped_v)
    if matrices_equal(flipped_vh, matrix2):
        return "flip vertical y flip horizontal"

    return "respuesta desconocida"

