def find_subarray_with_sum(n, s, vector):
    current_sum = 0
    start = 0
    for end in range(n):
        current_sum += vector[end]
        while current_sum > s and start <= end:
            current_sum -= vector[start]
            start += 1
        if current_sum == s:
            return start + 1, end + 1
    return -1
