def calcular_factores_primos_hasta(n):
    factores_primos = [0] * (n + 1)
    for i in range(2, n + 1):
        if factores_primos[i] == 0:
            for j in range(i, n + 1, i):
                factores_primos[j] += i
    return factores_primos

def encontrar_pares_ruth_aaron(a, b, factores_primos):
    pares = []
    for n in range(a, b):
        if factores_primos[n] == factores_primos[n + 1]:
            pares.append((n, n + 1))
    return pares


