def es_primo(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5)+1, 2):
        if n % i == 0:
            return False
    return True

def suma_digitos(n):
    return sum(int(d) for d in str(n))

def generar_primos_hasta(n):
    i = 2
    primos = []
    while len(primos) <= n:
        if es_primo(i):
            primos.append(i)
        i += 1
    return primos

