def sieve(limit):
    """
    Calcula y retorna una lista de números primos hasta 'limit' (inclusive)
    usando la Criba de Eratóstenes.
    """
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    primes = [i for i, prime in enumerate(is_prime) if prime]
    return primes

def digit_sum(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def generate_primes_by_index(max_index):

    upper_bound = 1600000
    primes_list = sieve(upper_bound)
    if len(primes_list) < max_index + 1:
        while len(primes_list) < max_index + 1:
            upper_bound *= 2
            primes_list = sieve(upper_bound)
    return primes_list

def main():
    import sys

    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    max_index_needed = 0

    test_cases = []

    for line in data:
        parts = line.strip().split()
        if len(parts) != 2:
            continue
        a, b = map(int, parts)
        test_cases.append((a, b))
        max_index_needed = max(max_index_needed, a, b)

    primes_list = generate_primes_by_index(max_index_needed)

    output_lines = []
    for a, b in test_cases:
        low, high = min(a, b), max(a, b)
        for pos in range(low, high + 1):
            prime = primes_list[pos]
            if digit_sum(pos) == digit_sum(prime):
                output_lines.append(f"{pos} {prime}")

    sys.stdout.write("\n".join(output_lines))

if __name__ == '__main__':
    main()

