def calcular_duraznos(k, T):
    total_pagado = 0
    cantidad_duraznos = 0
    precio_actual = k

    while total_pagado < T:
        total_pagado += precio_actual
        cantidad_duraznos += 1
        precio_actual *= 2  # El precio del siguiente durazno es el doble del anterior

    return cantidad_duraznos

