def GenerarPrim(x):
    UltimoNumeroP=2
    numeros=[True,True]+[True]*(x-1)
    i=UltimoNumeroP
    while UltimoNumeroP**2 <=x:
        i+=UltimoNumeroP
        while i <= x:
            numeros[i]=False
            i+=UltimoNumeroP
        j=UltimoNumeroP+1
        while j<x:
            if numeros[j]:
              UltimoNumeroP=j
              break
            j+=1
        i=UltimoNumeroP
    return [ i+2 for i,z in enumerate(numeros[2:]) if z]
