def desplazamiento(p):
    f = {}
    for l in p:
        if l.isalpha() or l == 'ñ':
            if l in f:
                f[l] += 1
            else:
                f[l] = 1
    mf = max(f.values())
    return mf
def cifrar(p, d):
    alf = 'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ'
    pc = ''
    for l in p:
        if l.isalpha() or l == 'ñ':
            idx = alf.index(l.upper())
            nl = alf[(idx + d) % len(alf)]
            pc += nl
        else:
            pc += l
    return pc
