def crear_diccionarios_alfabeto():
    letras = [
        'A', 'B', 'C', 'D', 'E', 'F', 'G',
        'H', 'I', 'J', 'K', 'L', 'M', 'N',
        'Ñ', 'O', 'P', 'Q', 'R', 'S', 'T',
        'U', 'V', 'W', 'X', 'Y', 'Z'
    ]
    letra_a_num = {letra: i+1 for i, letra in enumerate(letras)}
    num_a_letra = {i+1: letra for i, letra in enumerate(letras)}
    return letra_a_num, num_a_letra

def calcular_clave(palabra):
    from collections import Counter
    letras_solo = [c for c in palabra if c.isalpha()]
    if not letras_solo:
        return 1
    conteo = Counter(letras_solo)
    return max(conteo.values())

def cifrar_palabra(palabra, clave, letra_a_num, num_a_letra):

    # Letra de la clave inicial
    letra_clave = num_a_letra[(clave - 1) % 27 + 1]
    resultado = []
    resultado.append(letra_clave)

    for c in palabra:
        if c.isalpha():
            pos = letra_a_num[c]
            nueva_pos = (pos + clave - 1) % 27 + 1
            resultado.append(num_a_letra[nueva_pos])
        else:
            resultado.append(c)

    return ''.join(resultado)

def main():
    letra_a_num, num_a_letra = crear_diccionarios_alfabeto()
    try:
        while True:
            linea = input()
            if not linea.strip():
                continue
            k = int(linea)
            for _ in range(k):
                palabra = input().strip()
                clave = calcular_clave(palabra)
                codificada = cifrar_palabra(palabra, clave, letra_a_num, num_a_letra)
                print(codificada)
    except EOFError:
        pass

if __name__ == "__main__":
    main()

