import sys

def count_occurrences(uno, dos):
    i = 0
    ans = 0
    tam = len(uno)
    while i < len(uno):
        if (tam - i) >= len(dos):
            es = True
            for j in range(len(dos)):
                if uno[i + j] != dos[j]:
                    es = False
            if es:
                ans += 1
                i += len(dos)
            else:
                i += 1
        else:
            i += 1
    return ans

