    tres_ingredientes = 0
    un_ingrediente = 0
    dos_ingredientes = 0

    tres_ingredientes = min(jamon, tocino, huevo)

    jamon -= tres_ingredientes
    tocino -= tres_ingredientes
    huevo -= tres_ingredientes

    ingredientes = sorted([jamon, tocino, huevo], reverse=True)
    dos_ingredientes = min(ingredientes[0], ingredientes[1])

    if jamon >= tocino and jamon >= huevo:
        jamon -= dos_ingredientes
        if tocino >= huevo:
            tocino -= dos_ingredientes
        else:
            huevo -= dos_ingredientes
    elif tocino >= jamon and tocino >= huevo:
        tocino -= dos_ingredientes
        if jamon >= huevo:
            jamon -= dos_ingredientes
        else:
            huevo -= dos_ingredientes
    else:
        huevo -= dos_ingredientes
        if jamon >= tocino:
            jamon -= dos_ingredientes
        else:
            tocino -= dos_ingredientes

    un_ingrediente = max(jamon, tocino, huevo)

