def formas_no_atacan(n):
    if n < 2:
        return 0

    # Maneras en las que se atacan
    ataques_filas_columnas = 2 * (n * (n - 1) // 2) * n

    # Total de maneras de elegir dos posiciones para las reinas
    total_formas = (n * n * (n * n - 1)) // 2
    ataques_diagonales = 2 * (n - 1) * (2 * n - 1) * (n) // 6

    # Total formas donde no se atacan
    return total_formas - ataques_filas_columnas - ataques_diagonales

