    if N < 2:
        return 0

    misma_fila_columna = 2 * (N * (N - 1) // 2) * N
    total_formas = (N * N * (N * N - 1)) // 2
    mismo_diagomnal = 2 * (N - 1) * (2 * N - 1) * (N) // 6

    return total_formas - misma_fila_columna - mismo_diagomnal

while True:
    try:
        N = int(input())
        if N == 0:
            break

        print(dos_reinas(N))
    except:
        break

def count_ways(n):
    if n < 2:
        return 0 
    attack_ways = 0

    total_ways = n * n * (n * n - 1) // 2  

    for row in range(n):
        for col in range(n):

            attack_ways += (n - 1) + (n - 1)

            attack_ways += min(row, col) + min(n - 1 - row, n - 1 - col)

            attack_ways += min(row, n - 1 - col) + min(n - 1 - row, col)

    return total_ways - attack_ways // 2

while True:
    try:
        n = int(input())
        print(count_ways(n))
    except EOFError:
        break

def contar_formas_reinas(n):
    if n < 2:
        return 0
    total_posiciones = n * n
    ataques = 0

    for i in range(n):
        for j in range(n):
            ataques += (2 * (n - 1))
            ataques += min(i, j)
            ataques += min(i, n - j - 1)
            ataques += min(n - i - 1, j)
            ataques += min(n - i - 1, n - j - 1)
    total_formas = total_posiciones * (total_posiciones - 1) // 2

    total_ataques = ataques // 2
    return total_formas - total_ataques

