from collections import Counter
from math import gcd

def max_puntos_en_linea(n, puntos):
    if n == 0:
        return 0
    pendientes = Counter()

    for x, y in puntos:
        dx, dy = x, y
        g = gcd(dx, dy)
        dx //= g
        dy //= g
        if dx < 0 or (dx == 0 and dy < 0):
            dx, dy = -dx, -dy

        pendientes[(dx, dy)] += 1

    return max(pendientes.values())
def main():
    n = int(input())
    puntos = [tuple(map(int, input().split())) for _ in range(n)]
    resultado = max_puntos_en_linea(n, puntos)
    print(resultado)

if __name__ == "__main__":
    main()

import math
from collections import defaultdict

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

class Slope:
    def __init__(self, y, x):
        if x < 0:
            y = -y
            x = -x
        elif x == 0:
            y = 1  

        g = gcd(abs(y), abs(x))
        self.num = y // g
        self.den = x // g

    def __eq__(self, other):
        return self.num == other.num and self.den == other.den

    def __hash__(self):
        return hash((self.num, self.den))

def main():
    n = int(input()) 
    slope_count = defaultdict(int) 
    max_points = 0

    for _ in range(n):
        x, y = map(int, input().split()) 

        if x == 0 and y == 0:
            continue 

        slope = Slope(y, x)
        slope_count[slope] += 1

        max_points = max(max_points, slope_count[slope])

    print(max_points)

if __name__ == "__main__":
