from collections import defaultdict

def max_points_on_line(points):
    slope_count = defaultdict(int)

    for x, y in points:
        if x == 0 and y == 0:
            continue  # Ignorar el origen si está en la lista de puntos
        elif x == 0:
            slope = (1, 0)  # Línea vertical
        elif y == 0:
            slope = (0, 1)  # Línea horizontal
        else:
            g = gcd(x, y)  # Calcular el MCD
            slope = (y // g, x // g)  # Simplificar la fracción

        slope_count[slope] += 1

    # El máximo número de puntos en la misma línea
    return max(slope_count.values(), default=0)

