def max_points_on_line(points):
    if not points:
        return 0

    slope_count = defaultdict(int)

    for x, y in points:
        if x == 0:

            slope = ('inf', 1)  
        else:

            divisor = gcd(x, y)
            slope = (y // divisor, x // divisor)  

        slope_count[slope] += 1


