import math

def max_points_on_line(puntos):
    pendientes = defaultdict(int)
    max_puntos = 0

    for x, y in puntos:
        if x == 0 and y == 0:
            continue 

        if x == 0:  
            pendiente = ('inf', 0)
        elif y == 0:  
            pendiente = (0, 'inf')
        else:
            gcd = math.gcd(x, y)
            pendiente = (y // gcd, x // gcd) 


            if pendiente[1] < 0:
                pendiente = (-pendiente[0], -pendiente[1])

        pendientes[pendiente] += 1
        max_puntos = max(max_puntos, pendientes[pendiente])

    return max_puntos


