from math import gcd

def max_puntos_en_una_linea(puntos):
    pendientes = defaultdict(int)

    for x, y in puntos:
        if x == 0:
            pendiente = ('inf', 1)  
        else:
            g = gcd(x, y)  
            pendiente = (y // g, x // g)

            if pendiente[1] < 0:
                pendiente = (-pendiente[0], -pendiente[1])

        pendientes[pendiente] += 1


    return max(pendientes.values(), default=0)


