def separar_grupos(numeros):
    vistos = set()
    duplicados = set()
    izquierda = []

    alternar = True
    derecha = []
    for num in numeros:
        if num in duplicados:
            continue
        if num in vistos:
            duplicados.add(num)
            vistos.discard(num)
        else:
            vistos.add(num)

    for num in numeros:
        if num in vistos:
            if alternar:
                izquierda.append(num)
            else:
                derecha.append(num)
            alternar = not alternar

    print(len(izquierda), len(derecha))

