    if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == '#' or visited[x][y]:
        return 0
    visited[x][y] = True
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    count = 1
    for dx, dy in directions:
        count += dfs(grid, x + dx, y + dy, visited)
    return count

def count_accessible_places(grid):
    x_len = len(grid)
    y_len = len(grid[0])
    visited = [[False] * y_len for _ in range(x_len)]
    start_x = start_y = -1
    for i in range(x_len):
        for j in range(y_len):
            if grid[i][j] == '@':
                start_x, start_y = i, j
                break
        if start_x != -1:
            break
    return dfs(grid, start_x, start_y, visited)

