def factorizar_factorial(n):
    factorial = 1
    for i in range(2, n + 1):
        factorial *= i
    divisor = 2
    factorizacion = {}
    while factorial > 1:
        exponente = 0
        while factorial % divisor == 0:
            exponente += 1
            factorial //= divisor
        if exponente > 0:
            factorizacion[divisor] = exponente
        divisor += 1
    factorizacion_str = []
    for factor, exponente in factorizacion.items():
        if exponente == 1:
            factorizacion_str.append(f"{factor}(1)")
        else:
            factorizacion_str.append(f"{factor}({exponente})")

    return "*".join(factorizacion_str)

