def prime_factors_count(n):
    d = 2
    factors = {}
    while d * d <= n:
        while (n % d) == 0:
            if d in factors:
                factors[d] += 1
            else:
                factors[d] = 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = 1
    return factors
def factorial_prime_factors(n):
    prime_count = {}
    for i in range(2, n + 1):
        factors = prime_factors_count(i)
        for prime, count in factors.items():
            if prime in prime_count:
                prime_count[prime] += count
            else:
                prime_count[prime] = count
    return prime_count

def format_prime_factors(factors):
    sorted_factors = sorted(factors.items())
    result = []
    for prime, exponent in sorted_factors:
        result.append(f"{prime}({exponent})")
    return "*".join(result)

