import sys

def fibonacci(n):

    if n == 0:

        return 0

    elif n == 1:

        return 1

    a, b = 0, 1

    for _ in range(2, n + 1):

        a, b = b, a + b

    return b

def es_primo(n):

    if n <= 1:

        return False

    if n == 2 or n == 3:

        return True

    if n % 2 == 0 or n % 3 == 0:

        return False

    for i in range(5, isqrt(n) + 1, 6):

        if n % i == 0 or n % (i + 2) == 0:

            return False

    return True

def miller_rabin(n, k=5):

    if n <= 1:

        return False

    if n == 2 or n == 3:

        return True

    if n % 2 == 0:

        return False

    d, r = n - 1, 0

    while d % 2 == 0:

        d //= 2

        r += 1

    from random import randrange

    for _ in range(k):

        a = randrange(2, n - 1)

        x = pow(a, d, n)

        if x == 1 or x == n - 1:

            continue

        for _ in range(r - 1):

            x = pow(x, 2, n)

            if x == n - 1:

                break

        else:

            return False

    return True

