def aplicar_metodo_divisibilidad(n):
    pasos = []
    while n > 81:
        resto = n // 10
        ult_dig = n % 10
        pasos.append((resto, ult_dig))
        n = resto + ult_dig * 5
    return pasos, n

def verificar_divisibilidad(original, resultado_final):
    return (original % 7) == (resultado_final % 7)

def procesar_caso(n):
    pasos, resultado = aplicar_metodo_divisibilidad(n)
    es_correcto = verificar_divisibilidad(n, resultado)
    salida = ''.join(f"({a}, {b})" for a, b in pasos)
    salida += f" {resultado} {'correcto' if es_correcto else 'incorrecto'}"
    return salida

def procesar_entrada():
    t = int(input())
    for _ in range(t):
        n = int(input())
        print(procesar_caso(n))

if __name__ == "__main__":
    procesar_entrada()

def simulate_umbrella_usage(N, H, W, weather):
    home_umbrellas = H
    work_umbrellas = W
    result = []

    for day in weather:
        home_to_work, work_to_home = day
        carry_umbrella_to_home = 'N'
        carry_umbrella_to_work = 'N'

        # Viaje de casa al trabajo
        if home_to_work == 'Y':
            if home_umbrellas > 0:
                home_umbrellas -= 1
                carry_umbrella_to_work = 'Y'
            else:
                carry_umbrella_to_work = 'Y'
            work_umbrellas += 1
        elif work_umbrellas == 0:
            if home_umbrellas > 0:
                home_umbrellas -= 1
                carry_umbrella_to_work = 'Y'
            work_umbrellas += 1

        # Viaje del trabajo a casa
        if work_to_home == 'Y':
            if work_umbrellas > 0:
                work_umbrellas -= 1
                carry_umbrella_to_home = 'Y'
            else:
                carry_umbrella_to_home = 'Y'
            home_umbrellas += 1
        elif home_umbrellas == 0:
            if work_umbrellas > 0:
                work_umbrellas -= 1
                carry_umbrella_to_home = 'Y'
            home_umbrellas += 1

        result.append(f"{carry_umbrella_to_work} {carry_umbrella_to_home}")

    return result

