def decimal_a_factorial(n):
    if n == 0:
        return "0"
    i = 1

    resultado = []
    while n > 0:
        resultado.append(n % i)
        n = n // i
        i += 1

    resultado.reverse()
    return ''.join(map(str, resultado))

def factorial_a_decimal(f):
    num = f[::-1]
    decimal = 0
    for i in range(len(num)):
        decimal += int(num[i]) * factorial(i)
    return decimal

def factorial(n):
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

