def es_multiplo_de_11(numero):
    suma_impares = sum(int(numero[i]) for i in range(0, len(numero), 2))
    suma_pares = sum(int(numero[i]) for i in range(1, len(numero), 2))
    return (suma_impares - suma_pares) % 11 == 0

