import math


def buscar_potencia(a, b, c):
    p = a * b * c
    max_x, max_y = -1, -1
    for x in range(2, math.isqrt(p) + 1):
        y = 1
        potencia = x
        while potencia <= p:
            if potencia == p:
                if x > max_x:
                    max_x, max_y = x, y
            potencia *= x

            y += 1

    if max_x == -1:

        return "-1"

    else:

        return f"{a}*{b}*{c}={p}={max_x}**{max_y}"


