import math
def Potencia(a, b, c):
    p = a * b * c
    mx, my = -1, -1
    for x in range(2, math.isqrt(p) + 1):
        y = 1
        pt = x
        while pt <= p:
            if pt == p:
                if x > mx:
                    mx, my = x, y
            pt *= x

            y += 1

    if mx == -1:

        return "-1"

    else:

        return f"{a}*{b}*{c}={p}={mx}**{my}"

