def es_potencia(n):
    max_base = int(n**0.5) + 2
    mejores = (-1, -1)  
    for base in range(2, max_base):
        val = 1
        exp = 0
        while val < n:
            val *= base
            exp += 1
        if val == n:
            if base > mejores[0]:
                mejores = (base, exp)
    if mejores == (-1, -1):
        return None
    return mejores

