def binomioderodri(maxn):
    p = 2
    esta_prime = [True] * (maxn + 1)
    while (p * p <= maxn):
        if (esta_prime[p] == True):
            for i in range(p * p, maxn + 1, p):
                esta_prime[i] = False
        p += 1
    primes = [p for p in range(2, maxn + 1) if esta_prime[p]]
    return primes

def count_primos(primes, a, b):
    count = 0
    for prime in primes:
        if a <= prime <= b:
            count += 1
    return count
