def factores_primos(n):
    divisor = 2
    factor = []
    while divisor * divisor <= n:
        if n % divisor == 0:
            if divisor not in factor:
                factor.append(divisor)
            while n % divisor == 0:
                n //= divisor
        divisor += 1
    if n > 1 and n not in factor:
        factor.append(n)
    return len(factor)



