def x1(a):
    return [int(b) for b in str(a)]

def x2(c):
    return int(''.join(map(str, c)))

def x3(d):
    e = x1(d)
    f = sorted(e)
    g = x2(f)
    h = x2(f[::-1])
    return g, h

def x4(i):
    j = set()
    l = i
    k = 0
    if len(set(str(i))) == 1:
        return 1, 0
    while True:
        m, n = x3(l)
        o = n - m
        k += 1
        if o in j:
            return k - 1, o
        if o == l:
            return k, o
        j.add(o)
        l = o
        if k > 100:
            return -1, -1

